import React, { useEffect, useState } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { APP_INFO, FEATURES } from "../constants/AppConstants";
import "./LoginPage.css";

function FacebookIcon() {
  return (
    <svg width="22" height="22" viewBox="0 0 24 24" fill="currentColor">
      <path d="M22 12.06C22 6.51 17.52 2 12 2S2 6.51 2 12.06c0 5.02 3.66 9.18 8.44 9.94v-7.03H7.9v-2.91h2.54V9.85c0-2.51 1.49-3.9 3.77-3.9 1.09 0 2.24.2 2.24.2v2.47h-1.26c-1.24 0-1.63.78-1.63 1.58v1.86h2.78l-.44 2.91h-2.34V22c4.78-.76 8.44-4.92 8.44-9.94Z" />
    </svg>
  );
}
function GoogleIcon() {
  return (
    <svg width="22" height="22" viewBox="0 0 24 24" fill="currentColor">
      <path d="M21.35 11.1H12v2.9h5.35c-.24 1.4-1.68 4.1-5.35 4.1-3.22 0-5.85-2.67-5.85-5.95S8.78 6.2 12 6.2c1.83 0 3.06.78 3.76 1.45l2.56-2.47C16.77 3.6 14.6 2.7 12 2.7 6.98 2.7 2.9 6.86 2.9 12.1S6.98 21.5 12 21.5c6.92 0 9.35-4.86 9.35-8.86 0-.6-.06-1.04-.14-1.54Z" />
    </svg>
  );
}
function XIcon() {
  return (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor">
      <path d="M18.24 2.75h3.05l-6.66 7.61L22.5 21.25h-6.14l-4.8-6.28-5.5 6.28H2.99l7.13-8.15L2 2.75h6.29l4.34 5.74 5.61-5.74Zm-1.07 16.66h1.69L7.9 4.49H6.08l11.09 14.92Z" />
    </svg>
  );
}

export default function LoginPage() {
  const { login, loginAsGuest, isAuthenticated } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [guestLoading, setGuestLoading] = useState(false);
  const [resetMessage, setResetMessage] = useState("");

  const redirectTo = location.state?.from?.pathname || "/";

  useEffect(() => {
    if (isAuthenticated) {
      navigate(redirectTo, { replace: true });
    }
  }, [isAuthenticated, redirectTo, navigate]);

  async function handleSubmit(e) {
    e.preventDefault();
    setError("");
    if (!username.trim() || !password) {
      setError("Please enter both a username and a password.");
      return;
    }
    setSubmitting(true);
    try {
      await login(username.trim(), password);
      navigate(redirectTo, { replace: true });
    } catch (err) {
      setError(err.message || "Something went wrong. Please try again.");
    } finally {
      setSubmitting(false);
    }
  }

  async function handleGuest() {
    setError("");
    setGuestLoading(true);
    try {
      await loginAsGuest();
      navigate("/", { replace: true });
    } catch (err) {
      setError("Couldn't start a guest session. Please try again.");
    } finally {
      setGuestLoading(false);
    }
  }

  async function handleForgotPassword() {
    setResetMessage("");
    if (!username.trim()) {
      setError("Enter your username above first, then tap 'forgot password?'.");
      return;
    }
    setResetMessage(`If an account exists for "${username.trim()}", reset instructions were sent.`);
  }

  return (
    <div className="login-screen">
      <div className="login-blob login-blob--tr" aria-hidden="true" />
      <div className="login-blob login-blob--bl" aria-hidden="true" />

      <div className="login-topbar">
        <div className="login-logo">
          <span>campus</span>
          <span>Mobi</span>
        </div>
        <button type="button" className="signup-btn" onClick={() => setResetMessage("Sign-up isn't open yet — try Continue as Guest to explore CampusMobi.")}>
          SignUp ...
        </button>
      </div>

      <div className="login-stage">
        <div className="login-card">
          <h1>SignIn</h1>

          {error && <div className="error-banner">{error}</div>}
          {resetMessage && !error && (
            <div className="error-banner" style={{ color: "var(--lime)", borderColor: "rgba(215,242,58,0.4)", background: "rgba(215,242,58,0.08)" }}>
              {resetMessage}
            </div>
          )}

          <form className="login-form" onSubmit={handleSubmit} noValidate>
            <input
              className="field"
              type="text"
              placeholder="UserName ..."
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              autoComplete="username"
            />
            <input
              className="field"
              type="password"
              placeholder="password ..."
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoComplete="current-password"
            />

            <button type="button" className="forgot-link" onClick={handleForgotPassword}>
              forgot password?
            </button>

            <button type="submit" className="signin-btn" disabled={submitting}>
              {submitting ? "Signing in ..." : "SignIn ..."}
            </button>
          </form>

          {FEATURES.ENABLE_GUEST_MODE && (
            <>
              <div className="divider-row">
                <div className="line" />
                <span>or</span>
                <div className="line" />
              </div>
              <button
                type="button"
                className="guest-btn"
                onClick={handleGuest}
                disabled={guestLoading}
              >
                {guestLoading ? "Setting up guest session ..." : "Continue as Guest"}
              </button>
            </>
          )}

          <div className="social-row">
            <button type="button" className="social-item" onClick={() => setResetMessage("Facebook sign-in isn't connected yet.")}>
              <span className="social-circle"><FacebookIcon /></span>
              Facebook
            </button>
            <button type="button" className="social-item" onClick={() => setResetMessage("Google sign-in isn't connected yet.")}>
              <span className="social-circle"><GoogleIcon /></span>
              Google
            </button>
            <button type="button" className="social-item" onClick={() => setResetMessage("X sign-in isn't connected yet.")}>
              <span className="social-circle"><XIcon /></span>
              X
            </button>
          </div>
        </div>
      </div>

      <div style={{ position: "relative", zIndex: 2, textAlign: "center", color: "var(--text-faint)", fontSize: "0.78rem", paddingBottom: 18 }}>
        {APP_INFO.UNIVERSITY} · {APP_INFO.DOMAIN}
      </div>
    </div>
  );
}
